package com.bank.denomination;

import java.util.logging.Logger;

// Computes voucher denominations and fee realignment for National Bank of India.
public class DenominationService {
    private static final Logger log = Logger.getLogger(DenominationService.class.getName());

    // Greatest common divisor via the iterative Euclidean algorithm.
    public long gcd(long a, long b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            long temp = b;      // keep old b
            b = a % b;          // new b is the remainder
            a = temp;           // old b becomes a
        }
        long result = a;
        log.fine(() -> "gcd computed = " + result);
        return result;          // a holds the gcd when b hit zero
    }

    // Least common multiple, divide by gcd FIRST to avoid overflow.
    public long lcm(long a, long b) {
        if (a == 0 || b == 0) return 0;
        long g = gcd(a, b);
        long result = Math.abs(a / g * b);
        log.fine(() -> "lcm computed = " + result);
        return result;
    }
}
