package com.bank.denomination;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: largest voucher denomination and fee realignment day.
public class DenominationDemo {
    private static final Logger log = Logger.getLogger(DenominationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        DenominationService service = new DenominationService();

        // Rajesh (SAV2001) cashback total, Priya (CUR3001) cashback total.
        long rajeshCashback = 4800L;
        long priyaCashback  = 3600L;
        long denomination = service.gcd(rajeshCashback, priyaCashback);
        log.info(() -> "Largest voucher denomination for Rs." + rajeshCashback
                + " and Rs." + priyaCashback + " = Rs." + denomination);

        // Two recurring fees: every 12 days and every 18 days.
        long feePeriodA = 12L;
        long feePeriodB = 18L;
        long realignDay = service.lcm(feePeriodA, feePeriodB);
        log.info(() -> "Fees of every " + feePeriodA + " and " + feePeriodB
                + " days realign after " + realignDay + " days");
    }
}
